submissions.repair-original-dispatch-record-date:
def solve(data):
    if data['state'] == 'cancelled':
        return ''
    if data['version'] == 1:
        return data['dispatch_on']
    schedule = data['schedule']
    revised = schedule.get('revised_on')
    return revised if revised is not None else schedule['planned_on']

submissions.repair-original-expand-month-end-close:
from datetime import date, timedelta


def solve(data):
    start = date.fromisoformat(data['start'])
    end = date.fromisoformat(data['end'])
    holidays = {date.fromisoformat(value) for value in data['holidays']}
    day = timedelta(days=1)
    month = start.replace(day=1)
    result = []
    while month <= end:
        following = (month + timedelta(days=31)).replace(day=1)
        close = following - day
        while close >= month and (close.weekday() >= 5 or close in holidays):
            close -= day
        if close >= month and start <= close <= end:
            result.append(close.isoformat())
        month = following
    return result

submissions.repair-original-expire-event-id-suppress:
def solve(data):
    events = data['events']
    last = {}
    kept = []
    for index in sorted(range(len(events)), key=lambda i: events[i]['at']):
        row = events[index]
        if row['state'] != 'live':
            continue
        key, at = row['id'], row['at']
        if key not in last or at - last[key] >= data['horizon']:
            kept.append(index)
            last[key] = at
    return kept
